// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract Counter {

    uint public count;  // starts at 0 (default)

    // STATE CHANGING — writes to storage
    function increment() public {
        count++;         // count = count + 1
    }

    function decrement() public {
        count--;         // count = count - 1
    }

    function reset() public {
        count = 0;       // set back to zero
    }

    // VIEW — only reads, no cost externally
    function getCount() public view returns(uint) {
        return count;
    }

}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract UserIdentity {

    address public owner;
    address public lastCaller;

    // constructor: runs once at deployment
    constructor() {
        owner = msg.sender; // deployer becomes owner
    }

    // saves whoever calls this function
    function saveUser() public {
        lastCaller = msg.sender;
    }

    // returns the caller's own address
    function whoAmI() public view returns(address) {
        return msg.sender;
    }

    // checks if caller is the owner
    function isOwner() public view returns(bool) {
        return msg.sender == owner;
    }

}

