// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract ValueDemo {

    mapping(address => uint) public deposits;

    // returns the ETH amount sent with THIS call
    function deposit() public payable returns(uint) {
        deposits[msg.sender] += msg.value;
        return msg.value; // how much was sent
    }

    // check minimum deposit
    function depositMinimum() public payable {
        require(
            msg.value >= 0.01 ether,
            'Minimum deposit is 0.01 ETH'
        );
        deposits[msg.sender] += msg.value;
    }

    // view own deposit total
    function myDeposit() public view returns(uint) {
        return deposits[msg.sender];
    }

}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract AccessControl {

    address public owner;
    uint public vaultBalance;

    constructor() {
        owner = msg.sender;
    }

    // require: caller must be owner
    function ownerAction() public view returns(string memory) {
        require(msg.sender == owner, 'Not the owner');
        return 'Welcome, Owner!';
    }

    // require: value must be positive
    function deposit(uint _amount) public {
        require(_amount > 0, 'Amount must be greater than 0');
        vaultBalance += _amount;
    }

    // require: cannot withdraw more than balance
    function withdraw(uint _amount) public {
        require(msg.sender == owner, 'Not the owner');
        require(_amount <= vaultBalance,
            'Insufficient balance');
        vaultBalance -= _amount;
    }

}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract SimpleBank {

    address public owner;
    mapping(address => uint) public balances;

    constructor() {
        owner = msg.sender;
    }

    // receive ETH — credited to caller's balance
    function deposit() public payable {
        require(msg.value > 0, 'Send some ETH');
        balances[msg.sender] += msg.value;
    }

    // view contract's total ETH
    function getContractBalance()
        public view returns(uint)
    {
        return address(this).balance;
    }

    // view caller's individual deposit
    function myBalance() public view returns(uint) {
        return balances[msg.sender];
    }

    // owner-only: welcome message
    function ownerPanel()
        public view returns(string memory)
    {
        require(msg.sender == owner, 'Not Owner');
        return 'Welcome, Bank Owner!';
    }

}
